import numpy as np


def conv1d_full(x, k):
    # the textbook convolution, equal to NumPy's full convolution of x and k;
    # conv1d_valid(x, k), the unflipped valid slide, is defined for you
    k = np.asarray(k, dtype=float)
    z = np.zeros(len(k) - 1)
    xp = np.concatenate([z, np.asarray(x, dtype=float), z])
    return conv1d_valid(xp, k[::-1])

